"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../../../../components/sidebar";
import Navbar from "../../../components/Navbar";

export default function Edituser() {
  const router = useRouter();
  const params = useParams();
  
  // États
  const [etudiant, setEtudiant] = useState(null);
  const [groupes, setGroupes] = useState([]);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujets, setSujets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTuteur, setSelectedTuteur] = useState("");
  const [selectedSujet, setSelectedSujet] = useState("");

  // Récupérer l'ID depuis les paramètres
  const id = params?.id;

  useEffect(() => {
    console.log("ID actuel:", id);
    if (id) {
      loadAllData();
    }
  }, [id]);

  const loadAllData = async () => {
    setLoading(true);
    try {
      const [etudiantRes, groupesRes, tuteursRes, sujetsRes] = await Promise.all([
        axios.get(`http://localhost:5000/api/getetudiant/${id}`),
        axios.get("http://localhost:5000/api/groupes"),
        axios.get("http://localhost:5000/api/tuteurs"),
        axios.get("http://localhost:5000/api/sujets")
      ]);

      console.log("Données étudiant:", etudiantRes.data);
      console.log("Données tuteurs:", tuteursRes.data);
      console.log("Données sujets:", sujetsRes.data);

      setEtudiant(etudiantRes.data);
      setGroupes(groupesRes.data);
      setTuteurs(tuteursRes.data);
      setSujets(sujetsRes.data);
      
      // Initialiser les valeurs sélectionnées
      setSelectedTuteur(etudiantRes.data.idTuteur || "");
      setSelectedSujet(etudiantRes.data.idSujet || "");
    } catch (err) {
      console.error("Erreur lors du chargement des données:", err);
      setError("Erreur lors du chargement des données. Veuillez réessayer.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      const response = await axios.put(`http://localhost:5000/api/modifierGroupe/${id}`, {
        idGroupe: etudiant.idGroupe,
        idTuteur: selectedTuteur,
        idSujet: selectedSujet
      });

      console.log("Réponse modification:", response.data);
      alert("Modifications enregistrées avec succès!");
      router.push('/users/resdeffect/');
    } catch (err) {
      console.error("Erreur lors de la modification:", err);
      alert("Erreur lors de la modification. Veuillez réessayer.");
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative">
          {error}
        </div>
      </div>
    );
  }

  if (!etudiant) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="bg-yellow-100 border border-yellow-400 text-yellow-700 px-4 py-3 rounded relative">
          Étudiant non trouvé
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-screen bg-gray-100">
      <Sidebar />
      <div className="flex flex-col w-full">
        <Navbar />
        <div className="flex flex-1 justify-center items-center p-4">
          <div className="bg-white p-8 rounded-2xl shadow-lg w-full max-w-lg">
            <h1 className="text-2xl font-bold text-gray-800 text-center mb-6">
              Modifier les informations de {etudiant.nom} {etudiant.prenom}
            </h1>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nom</label>
                  <input
                    type="text"
                    value={etudiant.nom || ''}
                    className="w-full px-3 py-2 border rounded-md bg-gray-100"
                    readOnly
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Prénom</label>
                  <input
                    type="text"
                    value={etudiant.prenom || ''}
                    className="w-full px-3 py-2 border rounded-md bg-gray-100"
                    readOnly
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Groupe</label>
                <input
                  type="text"
                  value={etudiant.idGroupe || 'Non assigné'}
                  className="w-full px-3 py-2 border rounded-md bg-gray-100"
                  readOnly
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tuteur</label>
                <select
                  value={selectedTuteur}
                  onChange={(e) => setSelectedTuteur(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                >
                  <option value="">Sélectionner un tuteur</option>
                  {tuteurs.map((tuteur) => (
                    <option key={tuteur.idTuteur} value={tuteur.idTuteur}>
                      {tuteur.nomTuteur} {tuteur.prenomTuteur}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Sujet</label>
                <select
                  value={selectedSujet}
                  onChange={(e) => setSelectedSujet(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                >
                  <option value="">Sélectionner un sujet</option>
                  {sujets.map((sujet) => (
                    <option key={sujet.idSujet} value={sujet.idSujet}>
                      {sujet.nomSujet}
                    </option>
                  ))}
                </select>
              </div>

              <button
                type="submit"
                className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors mt-4"
              >
                Enregistrer les modifications
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
